import{k as e,o as t}from"./workshop-CLwOpcZb.js";import{i as n,n as r,r as i,t as a}from"./focus-B32ScESv.js";import{a as o,o as s,s as c}from"./videos-C4EM_MOp.js";var l=`Collar sizing diagram. 1: with the head neutral, follow a line from the chin straight back until it crosses the sternomastoid, then count fingerbreadths down to the top of the trapezius. 2: the collar opened out flat; put the same fingers on it from the sizing line down to the bottom edge of the hard plastic, not the foam pad, and choose the nearest size — between two, start smaller.`,u=e=>`s-`+e.toLowerCase().replace(/[^a-z0-9]+/g,`-`).replace(/^-|-$/g,``),d=[{id:`1`,short:`FIFA PEAP & roles`,title:`FIFA Pre-Match Emergency Action Plan (PEAP)`,subtitle:`Roles & responsibilities of team members, positioning & team ergonomics`,sections:[{title:`The medical set piece`,blocks:[{kind:`text`,text:`A pitchside emergency should be rehearsed before kick-off: clear plan, clear roles, correct positioning, ready equipment and closed-loop communication.`},{kind:`list`,items:[`The team doctor enters first, followed by the rest of the medical team.`,`Team leader (Black 1) — leads, ideally hands-off, and steps in if a job is not being done.`,`Around the player: Orange 2 (directly behind the head), Red 3 (chest), Blue 4 (pelvis), White 5 (legs) and Green 6 (bag and AED, at the head on the player's left).`]}]},{title:`Before kick-off: 5 key PEAP components`,blocks:[{kind:`cards`,items:[{title:`M — Meeting`,sub:`Who is involved?`,lines:[`Home team doctor`,`Visiting team doctor`,`Venue medical officer`,`Pitchside paramedics`]},{title:`C — Contacts`,sub:`Who do we call and where do we go?`,lines:[`Emergency numbers`,`Access / egress gates`,`Ambulance location`,`Receiving hospital`]},{title:`R — Roles & positioning`,sub:`Who does what and where?`,lines:[`Assign the team leader and the five colour roles`,`Brief any extrication team the venue provides`,`Confirm positions`,`Brief the team`]},{title:`E — Equipment`,sub:`Is everything ready?`,lines:[`Emergency care bag`,`AED + pads`,`Oxygen + BVM`,`Scoop / spinal board / basket + straps`]},{title:`T — Training`,sub:`Have we rehearsed?`,lines:[`Rehearse the critical scenarios before the event`,`Sudden cardiac arrest · cervical spine injury · trauma`,`Every colour practises its own role, with the real equipment`,`Debrief, then fix the gaps`]}]},{kind:`remember`,text:`M-CRET = Meet → Call → Position → Check → Train`},{kind:`defs`,items:[{term:`FIFA — before the tournament`,text:`The whole medical team trains in the FIFA set piece with the FIFA Match Doctor (usually Black, the team leader) 5–7 days before the first match, on the standard FIFA equipment.`},{term:`FIFA — on matchday`,text:`Between 2 hours and 1 hour before kick-off the team runs moulages (simulations) of the most critical scenarios, led by the FIFA Match Doctor.`},{term:`FIFA — everywhere`,text:`Use and rehearse the PEAP in all football settings — training sessions as well as matches — adapted to the site and the expertise available.`},{term:`How often`,text:`Practise the emergency plan at least once a year with everyone likely to respond, and review it briefly with the home and visiting medical staff before each competition.`},{term:`How to rehearse`,text:`Hands-on and scenario-based, at different places in the venue: sudden cardiac arrest, head and neck injury, heat stroke and limb injuries. Record when, where, who took part and which scenarios.`},{term:`After a real emergency`,text:`Debrief with everyone involved and use it to improve the plan.`},{term:`Why it matters`,text:`Aim for the first shock within 3 minutes of collapse. In one US study, 89% of school athletes survived a cardiac arrest when CPR and defibrillation were prompt — and survival was higher with an AED already on site.`}]},{kind:`text`,text:`Sources: FIFA Medical Set Piece — Protocols for on-field interventions (2025); consensus on sudden cardiac arrest on the field of play (Br J Sports Med, 2017); NATA position statement on emergency action plans in sport (J Athl Train, 2024).`}]},{title:`Golden rule: non-contact collapse`,blocks:[{kind:`alert`,title:`Presume sudden cardiac arrest (SCA) until proven otherwise`,text:`ENTER IMMEDIATELY → ASSESS → START CPR → APPLY THE AED WITHIN 30 SECONDS OF IT ARRIVING. Do not delay CPR / defibrillation for C-spine or fracture assessment in a non-contact collapse.`},{kind:`info`,title:`2025 resuscitation guidelines: call at once`,text:`The Resuscitation Council UK's 2025 guidelines say to call for help for anyone who is unresponsive, without first waiting to judge their breathing. On the pitch that is the set piece already: the team enters at once, Black makes sure the ambulance is called and Green brings the AED. Red's 10-second check of breathing and pulse decides on compressions — it never holds up the call.`}]},{title:`Medical team members`,blocks:[{kind:`table`,head:[`Role`,`Position`,`Main responsibility`],rows:[[`Team leader (Black 1)`,`Player's left, level with the chest`,`Hands off, in overall control: steps in if a job is not being done. CPR/AED flow, the transfer plan, ambulance and referee liaison.`],[`Head (Orange 2)`,`Directly behind the head, in line with the body`,`Manual in-line stabilisation and airway; i-gel and bag in cardiac arrest; commands the log roll.`],[`Chest (Red 3)`,`Player's right, level with the chest`,`A-c-B-C-D-E assessment and treatment; chest compressions 100–120/min with full recoil.`],[`Pelvis (Blue 4)`,`Player's right, level with the pelvis`,`Oxygen at 15 L/min; takes the PELVIS in the log roll; takes over compressions at 2 minutes.`],[`Legs (White 5)`,`Player's right, level with the lower legs`,`Brings the scoop and splints; takes the LEGS in the log roll; assists as directed.`],[`Equipment (Green 6)`,`At the head, on the player's left`,`FIFA bag and AED; hands equipment to Red; applies the AED and checks all clear before a shock.`]]},{kind:`defs`,items:[{term:`Six roles`,text:`Black, Orange, Red, Green, Blue and White — the colours on FIFA's PEAP poster.`},{term:`Numbers`,text:t.numberNote},{term:`Orange's position`,text:`This guide places Orange directly behind the head, in line with the body, for manual in-line stabilisation. FIFA's poster marks Orange at the head.`},{term:`Smaller teams`,text:`One person can cover more than one role if they are able to. Every role still has to be filled.`},{term:`Extrication team`,text:t.stretcherNote}]},{kind:`text`,text:`FIFA ECM: the Chest member should be one of the most experienced — they lead if no one else can. Pelvis and Legs need no medical skills but must be trained in the log roll. First aiders and paramedics only help if they are part of the plan.`}]},{title:`Entering the pitch (FIFA rules)`,blocks:[{kind:`list`,ordered:!0,items:[`The referee assesses the incident.`,`If needed, the referee signals the team doctor onto the pitch.`,`Only then, if needed, the referee calls the medical team — both hands held as if carrying a stretcher.`]},{kind:`alert`,title:`Exception: non-contact collapse`,text:`A player who collapses without contact is treated as sudden cardiac arrest — the medical team runs on without waiting for the referee's signal.`},{kind:`image`,src:e(`/img/fifa/onfield/access-rules.jpg`),alt:`FIFA rules for accessing the pitch, with the referee's stretcher signal`,caption:`Referee's stretcher signal and the non-contact-collapse exception. FIFA Medical Set Piece — Protocols for on-field interventions (v3, March 2025). © FIFA`}]},{title:`Sideline position and ready position`,blocks:[{kind:`list`,items:[`At FIFA matches the medical team sits to the left of Team A's bench, with the extrication kit set up beside the bench.`,`The team leader may call the team into the “ready” position.`,`Ready: move along the touchline to the point closest to the incident and squat in your assigned position with the stretcher.`,`Not needed: return to your seats, passing behind the team benches where possible.`]},{kind:`image`,src:e(`/img/fifa/onfield/ready-position.jpg`),alt:`Pitch diagram: move along the touchline to the level of the incident; team squatting in the ready position with the stretcher`,caption:`Move along the touchline to the level of the incident, then the ready position. FIFA Medical Set Piece — Protocols for on-field interventions (v3, March 2025). © FIFA`},{kind:`image`,src:e(`/img/fifa/onfield/bench.jpg`),alt:`Pitch diagram showing the medical team seated left of Team A's bench, with two basket stretchers in front`,caption:`Where the medical team sits. FIFA Medical Set Piece — Protocols for on-field interventions (v3, March 2025). © FIFA`},{kind:`defs`,items:[{term:`Medical team at FIFA matches`,text:`8–9 members: one emergency physician experienced in out-of-hospital care plus paramedics / health professionals doing BLS and ALS, with 2–3 reserves. The same team works every match at a venue.`},{term:`Training`,text:`The whole team trains in the FIFA set piece with the FIFA Match Doctor 5–7 days before the first match, on the standard FIFA equipment.`},{term:`FIFA Match Doctor`,text:`Usually Black, the team leader. Sits with and leads the team, reviews injury mechanisms on a replay device (often with a remote injury spotter), makes their own assessment, calls the ready position, and enters for potentially serious injury or concussion — then directs when the team comes on with the equipment.`}]}]},{title:`Matchday principles`,blocks:[{kind:`defs`,items:[{term:`Kick-off −2 h`,text:`Team present, equipment checked; player medical centre staffed.`},{term:`−2 h to −1 h`,text:`Moulages (simulations) of the most critical scenarios, led by the FIFA Match Doctor.`},{term:`Half-time · cool-down`,text:`Medical team always present.`},{term:`Post-match`,text:`Medical centre staff stay until the last player has left the stadium.`}]},{kind:`list`,items:[`Everyone knows their PEAP colour, wears their bib and shows no team bias.`,`Equipment set up next to the bench; no phones, photos or food pitchside.`]},{kind:`image`,src:e(`/img/fifa/onfield/timeline.jpg`),alt:`FIFA matchday timeline for the medical team`,caption:`FIFA matchday timeline. FIFA Medical Set Piece — Protocols for on-field interventions (v3, March 2025). © FIFA`}]},{title:`FIFA Skill Zone: sideline and set-up`,blocks:[{kind:`text`,text:`FIFA's own films of the first seconds of the set piece: where the team waits, how it enters, and how the kit is laid out around the player.`},{kind:`video`,clip:c.sideline},{kind:`video`,clip:c.setup}]},{title:`Pitchside positioning & team ergonomics`,blocks:[{kind:`positions`},{kind:`text`,text:`Extrication kit: below the feet, in line with the player. Basket 2–3 basket lengths from the feet; scoop taken out, opened and split, laid between the feet and the basket.`},{kind:`defs`,items:[{term:`Equipment zone`,text:`AED + O2 + emergency care bag at the player's head / left side.`},{term:`Extrication zone`,text:`Below the player's feet, in line with the body: basket 2–3 basket lengths from the feet, scoop opened out and split between the feet and the basket. Kept back until required.`},{term:`Team leader`,text:`Hands-off, with a full view of the whole scene. Keep the working area clean and uncluttered.`}]}]},{title:`Extrication set piece`,blocks:[{kind:`remember`,text:`PREPARE → TILT → SCOOP → STRAP → BASKET → GO`},{kind:`list`,items:[`Orange (the head) commands a gentle 15–20 degree tilt.`,`Reconnect the scoop head first, then feet.`,`Strap: Chest → Pelvis → Legs → Head.`]},{kind:`defs`,items:[{term:`Medical kit (FIFA)`,text:`FIFA bag + oxygen to one side of the head; one person hands out equipment.`},{term:`Extrication kit (FIFA)`,text:`Basket in line with the feet, 2–3 basket lengths away. Scoop out of the basket, extended and split between basket and player.`},{term:`Extrication team, if the venue has one`,text:`Stand or kneel beside the scoop and basket, facing the player, and wait for the team leader. One stays free to pass the scoop and slide the basket in.`}]},{kind:`text`,text:`The set piece above is for trauma. For a cardiac arrest in progress the player is moved on a long spinal board (a scoop can also be used) with the AED strapped on as one unit — see the cardiac arrest module.`},{kind:`list`,items:[`FIFA team kit (two identical sets): basket stretcher, split scoop or spine board, head blocks, cervical collar, straps or spider; AED; oxygen bottle; splints; an emergency bag the team knows well.`,`Entering: Green carries the emergency bag; the others carry the basket with the scoop / board, head blocks, collar and straps inside.`]},{kind:`image`,src:e(`/img/fifa/onfield/extrication-setup.jpg`),alt:`FIFA extrication set-up: bag and oxygen at the head, board or scoop between player and basket, basket 2–3 lengths from the feet`,caption:`Extrication set-up: 1 bag + oxygen left of the head · 2 basket 2–3 lengths from the feet · 3 scoop / board laid out between them. FIFA Medical Set Piece — Protocols for on-field interventions (v3, March 2025). © FIFA`},{kind:`image`,src:e(`/img/fifa/onfield/equipment.jpg`),alt:`Medical team equipment at FIFA matches laid out: basket stretcher with scoop, collar and straps`,caption:`Medical team equipment at FIFA matches. FIFA Medical Set Piece — Protocols for on-field interventions (v3, March 2025). © FIFA`}]},{title:`Closed-loop communication`,blocks:[{kind:`remember`,text:`NAME → COMMAND → REPEAT → CONFIRM`},{kind:`text`,text:`Example — Team leader: “Green, apply the AED.” Green: “Applying AED.” Green: “AED attached.”`}]},{title:`Pocket summary`,blocks:[{kind:`defs`,items:[{term:`Before match`,text:`M-CRET: Meet – Call – Position – Check – Train`},{term:`Non-contact collapse`,text:`SCA → CPR → AED the moment it arrives. The team leader calls any lift.`},{term:`Leadership`,text:`Hands off — eyes up. Command and confirm.`},{term:`Extrication (trauma)`,text:`Orange commands. Tilt – Scoop – Strap – Basket.`}]}]}],source:`FIFA Emergency Care Manual, Ch.1; FIFA's PEAP poster; and FIFA's protocols for on-field interventions during matches (tournament team size, timings and bench position).`},{id:`2`,short:`Cardiac arrest`,title:`Approach to Pitchside Cardiac Arrest`,subtitle:`Part 1 — BLS + AED · Part 2 — the transfer: the ambulance to the player, mechanical CPR, and the 10-second carry only as a last resort`,sections:[{title:`Team member roles & equipment`,blocks:[{kind:`steps`,items:[...t.roles.map(e=>({title:`${e.role} — brings: ${e.bring}`,who:[e.id],lines:[e.stand]}))]}]},{title:`Step by step`,blocks:[{kind:`video`,clip:s[0]},{kind:`steps`,items:t.steps.map(e=>({title:`${e.n} · ${e.title} (${e.time})`,who:[...e.who],lines:[...e.lines]}))}]},{title:`Time to the first shock`,blocks:[{kind:`text`,text:`The shock is what stops VF; good CPR keeps the brain and heart supplied until it comes. Drag the clock and see what each minute costs — without CPR, and with CPR from the start.`},{kind:`survival`},{kind:`link`,to:`/cases`,label:`Practise the decisions: case simulator →`,text:`Make the calls with a live monitor — non-contact collapse, and a ball to the chest.`}]},{title:`AED pads — practise in 3D`,blocks:[{kind:`text`,text:`You are Green 6 and the AED has just arrived: expose the chest, place both pads, hands off for the analysis, call everyone clear, then shock. The AED talks you through it and the clock runs to the shock.`},{kind:`aed-trainer`}]},{title:`Airway & ventilation in arrest`,blocks:[{kind:`defs`,items:[{term:`FIFA — 3 keys to survival`,text:`1 Recognise SCA · 2 Early good-quality compressions · 3 Early, safe defibrillation.`},{term:`Pads`,text:`Anterolateral, lateral pad in the mid-axillary line — keep compressing while the pads go on.`}]},{kind:`list`,items:[`i-gel is FIFA's adjunct of choice: one person holds it and squeezes the bag.`,`Bag with reservoir on oxygen at 15 L/min — better than a face mask + Guedel (two-person, poorer seal).`,`Continuous compressions, one breath every 10th compression. Leak → pause for 30:2.`,`Let the bag refill after each squeeze. Watch for symmetrical chest rise.`,`No i-gel: use the adjunct you know best (OPA or NPA) with a face mask.`]},{kind:`info`,title:`Oxygen at the shock`,text:`FIFA's 2025 on-field protocol: remove oxygen before the shock, unless it is on a closed loop such as an LMA (i-gel) — then it can stay connected. With a face mask only, take the mask and oxygen away for the shock and replace them straight after. The 2022 manual's older advice was to turn the oxygen off or disconnect it.`}]},{title:`Advanced life support (if trained)`,blocks:[{kind:`table`,head:[`Rhythm`,`Drug`],rows:[[`Shockable (VF / pVT)`,`Adrenaline 1 mg IV after the 3rd shock, then every 3–5 min. Amiodarone 300 mg after the 3rd shock; 150 mg after the 5th.`],[`Non-shockable (asystole / PEA)`,`Adrenaline 1 mg IV as soon as possible, then every 3–5 min.`]]},{kind:`text`,text:`Good compressions and early defibrillation matter most — do not let ALS distract from them. Reversible causes on the pitch: hypoxia, hypovolaemia, hypo/hyperthermia, tension pneumothorax.`},{kind:`alert`,title:`Every minute counts`,text:`For every minute without return of circulation, the chance of a good outcome falls by up to 10% (FIFA on-field protocols).`},{kind:`text`,text:`Moving the player: after the third shock and medications, the team leader considers moving the player. FIFA's advice is to bring the ambulance onto the pitch to the player wherever possible, and to fit a mechanical chest-compression device (LUCAS), where available and the team is trained on it, so compressions continue during the move. The 10-second stop-and-start carry is a last resort.`}]}],source:`FIFA on-field protocols (Version 3, March 2025) and the FIFA Emergency Care Manual, Ch.3. Where the two differ, the newer protocols are followed.`},{id:`3`,short:`Primary survey`,title:`Approach to Pitchside Injury Care`,subtitle:`Focused primary survey vs complete primary survey`,sections:[{title:`Definition of primary survey`,blocks:[{kind:`list`,items:[`A rapid, structured assessment.`,`Performed to identify life- or limb-threatening injuries.`,`When present, immediate intervention must be carried out.`,`Designed to enable clinicians to perform evaluations efficiently.`]}]},{title:`Protocol selection — focused vs complete 1° survey`,blocks:[{kind:`cards`,items:[{title:`Complete primary survey`,sub:`Airway, C-spine, Breathing, Circulation, Disability, Exposure`,lines:[`Mechanism of injury concerning or unclear, or player / referee / teammate responses raise clinical concern.`,`Safer, minimises the risk of missing significant secondary injuries, and builds fluency through repeated practice.`]},{title:`Focused primary survey`,sub:`Only the specifically suspected injured body part`,lines:[`Mechanism clearly witnessed, injury isolated, responses unconcerning, player confirms no other symptoms, and clinical instinct supports an isolated injury.`]}]},{kind:`alert`,title:`Safety transition rule`,text:`If any concern arises or the player's condition changes, immediately switch to a complete primary survey.`},{kind:`image`,src:e(`/img/stations/s3-pathway-v2.png`),alt:`Initial assessment flow chart: purple focused primary survey pathway, green complete primary survey pathway`,caption:`Initial assessment (FIFA Emergency Care Manual, Figure 6). Purple: focused 1° survey — isolated, unconcerning injury. Green: complete 1° survey — protect the cervical spine and assess fully. Any concern or change in condition → complete survey.`}]},{title:`Pre-survey scan & safety checks`,blocks:[{kind:`defs`,items:[{term:`1 · PPE`,text:`Don personal protective equipment before entering the pitch or assessing.`},{term:`2 · Danger`,text:`Check for immediate environmental hazards.`},{term:`3 · 5-second rapid scan`,text:`Signs of upper airway obstruction · central pulse · catastrophic haemorrhage.`}]}]},{title:`A — Airway & cervical spine`,blocks:[{kind:`defs`,items:[{term:`Look`,text:`Facial trauma: wounds, swelling, haematoma, bleeding, deformity, foreign bodies.`},{term:`Listen`,text:`Upper airway obstruction: stridor, gurgling, snoring, choking, hoarseness.`},{term:`Feel`,text:`Facial tenderness, swelling or structural deformity.`},{term:`Quickest method`,text:`Speak directly to the player to assess airway patency.`}]},{kind:`text`,text:`If obstruction is present:`},{kind:`list`,items:[`Manual opening: jaw thrust (preferred in trauma — no neck movement). Head-tilt/chin-lift is contraindicated with suspected trauma.`,`Suction bleeding, secretions or vomitus while evaluating the gag reflex with the suction catheter.`,`Adjuncts: OPA if the gag reflex is absent; consider an NPA if a gag reflex is present (best tolerated). NPA: relative contraindication with suspected base-of-skull fracture.`,`High-flow oxygen via BVM or non-rebreather mask at 15 L/min — as soon as it arrives; do not wait for the survey to finish.`,`Advanced: consider an i-gel LMA pitchside in cardiac arrest; intubation / RSI later at the medical base, ambulance or hospital.`]},{kind:`text`,text:`FIFA: fix each problem before moving on — an obstruction is treated (jaw thrust, suction, adjunct) before assessing breathing. Never let players put fingers in a player's mouth. See the airway skill films on the Films page.`},{kind:`text`,text:`Cervical spine management:`},{kind:`list`,items:[`Initiate Manual In-Line Stabilisation (MILS) and palpate for cervical spine tenderness.`,`Early collar application is not required if the player is conscious and alert — alert players naturally splint their neck.`,`Apply a cervical collar if you are unable to clear the cervical spine — as part of extrication, not early in the survey (FIFA). Clearing can wait until the primary survey is done.`,`Use the NSAID mnemonic to decide whether the spine can be cleared on-field.`]},{kind:`defs`,items:[{term:`N`,text:`Neurological deficit (numbness, weakness)`},{term:`S`,text:`Spinal midline tenderness (on palpation)`},{term:`A`,text:`Altered mental status (GCS < 15)`},{term:`I`,text:`Intoxication`},{term:`D`,text:`Distracting injury (severe enough to mask spinal pain)`}]},{kind:`alert`,text:`Any NSAID feature present → the spine cannot be cleared; extricate in a collar. The player must also actively rotate the neck 45° laterally (the player moves, not the clinician), and the mechanism must not be concerning (e.g. axial load). Intoxication includes strong analgesics such as codeine. (NSAID here is a spinal-clearance mnemonic, not the drug class.)`},{kind:`text`,text:`FIFA: a player shouting or screaming has a patent airway. Signs of obstruction: gurgling, snoring, choking, stridor, cyanosis, no breathing effort — treat at once and give oxygen. Head-tilt/chin-lift only if there is no suspicion of trauma.`},{kind:`defs`,items:[{term:`FIFA — clearing the cervical spine (all needed)`,text:`1 No midline tenderness · 2 GCS 15 · 3 No distracting injury · 4 No neurology · 5 No concerning mechanism (e.g. fall onto the head, axial load) · 6 Active rotation of 45° to each side. The manual adds a seventh: no intoxication.`}]}]},{title:`B — Breathing`,blocks:[{kind:`video`,clip:c.handsOn},{kind:`text`,text:`Pitchside breathing assessment is limited — use a focused “hands-on 1, 2, 3” approach.`},{kind:`defs`,items:[{term:`1 observation`,text:`Respiratory rate — plus chest movement, deformity, flail segment, bruising, open wounds.`},{term:`2 hands on 3 places`,text:`1. Neck · 2. Anterior chest wall · 3. Posterolateral chest wall.`},{term:`Assess`,text:`Pain, surgical emphysema (crackling under the skin), swelling, asymmetry.`}]},{kind:`text`,text:`Listen as you approach: gurgling / stridor = upper airway; wheeze = lower airway; coughing is reassuring. Watch the trend. Auscultation has no value inside a noisy stadium. No respiratory effort → cardiac arrest protocol (skill module 2).`}]},{title:`C — Circulation & haemorrhage control`,blocks:[{kind:`text`,text:`Check for active haemorrhage and evaluate CCTVR (Colour, Capillary refill, Temperature, Voluntary movement / pulse, Response).`},{kind:`defs`,items:[{term:`1 observation`,text:`Pulse — rate, volume and trend. Exercise tachycardia should settle; a worsening tachycardia is concerning.`},{term:`2 hands · Abdomen`,text:`Inspect and palpate all 4 quadrants.`},{term:`2 hands · Pelvis`,text:`Feel posterior → lateral → anterior. No downward pressure — DO NOT SPRING THE PELVIS.`},{term:`2 hands · Long bones`,text:`Femurs down to the ankles. A fractured femur can lose up to 1.5 L of blood.`}]},{kind:`list`,items:[`Direct pressure to control active bleeding — this takes priority in the survey.`,`Splint suspected fractures (reduces bleeding and pain).`,`Utilise a scoop stretcher to minimise movement during handling (~15° tilt vs a 90° log roll onto a board).`,`Capillary refill centrally: press the sternum for 5 seconds; skin should pink up within 2 seconds. A normal CRT does not exclude bleeding.`,`On-pitch BP has almost no value — measure it off the pitch with a properly fitted cuff.`,`Radial pulse: it relates to blood pressure, but studies differ and no single pressure figure can be attached to it. An ABSENT radial pulse is extremely concerning — think cardiac arrest.`,`Check blood glucose in any confused or collapsed player.`]}]},{title:`D — Disability & neurological status`,blocks:[{kind:`table`,head:[`AVPU (preferred)`,`GCS`],rows:[[`Alert`,`15`],[`Voice`,`13`],[`Pain`,`8`],[`Unresponsive`,`3`]]},{kind:`alert`,text:`Any score other than Alert mandates immediate removal from the field of play. Alert does NOT exclude concussion.`},{kind:`link`,to:`/focus`,label:`Concussion assessment (FOCUS)`,text:`Suspected concussion? Follow FIFA's on-pitch assessment, step by step.`},{kind:`list`,items:[`Pupils: size and reactivity — a baseline. A unilateral fixed, dilated pupil with a falling GCS = emergency transfer to neurosurgery.`,`Rapidly scan for unilateral neurological deficits.`,`Ask about numbness or weakness.`,`Observe limb movements and ask the player to move their limbs.`,`Assess balance and gait when returning the player to standing, if appropriate.`]},{kind:`text`,text:`FIFA “Hands On 1, 2, 3” for D: 1 observation = AVPU · 2 pupils (equal and reactive?) · 3 places — sensation and movement in the arms, upper legs and lower legs.`}]},{title:`E — Exposure & extrication`,blocks:[{kind:`text`,text:`Complete necessary exposure and safely extricate the player from the pitch.`},{kind:`remember`,text:`EXTRICATION KIT BELOW THE FEET, IN LINE WITH THE PLAYER`},{kind:`text`,text:`Set up below the feet (FIFA): basket in line with the player, 2–3 basket lengths from the feet; scoop out of the basket, extended and split, laid between the feet and the basket.`}]},{title:`Common pitchside injuries`,blocks:[{kind:`text`,text:`After the primary survey: what to check and do for the eye, nose, teeth, shoulder, knee, ankle and the rest — with the Ottawa rules for who needs an X-ray.`},{kind:`link`,to:`/injuries`,label:`Injury map: tap where it hurts →`,text:`Body map, pitchside cards and the Ottawa ankle, foot and knee rules.`}]}],source:`FIFA Emergency Care Manual, Ch.2. The 5-second scan and the NSAID and CCTVR memory aids are practical additions, not from the manual.`},{id:`4`,short:`Immobilisation`,title:`Immobilisation`,subtitle:`Collar, head immobiliser, spinal board, scoop, basket, splints and slings`,sections:[{title:`Principles of immobilisation`,blocks:[{kind:`list`,items:[`Prioritise life-threatening problems before immobilisation.`,`Use MILS when cervical spine injury is suspected.`,`Choose the device by suspected injury, player condition, environment and extraction plan.`,`Minimise unnecessary movement during assessment, transfer and extrication.`,`Explain the procedure to the player; coordinate all movement with one clear leader.`,`Assess distal circulation, sensation and movement before and after limb immobilisation.`,`Reassess ABC and neurological status after immobilisation and after every transfer.`]},{kind:`remember`,text:`ASSESS → STABILISE → IMMOBILISE → SECURE → REASSESS`},{kind:`info`,title:`Teaching note: collars, first aiders and medical teams`,text:`International first-aid guidance (ILCOR and the European Resuscitation Council) advises first-aid providers not to apply cervical collars routinely: fitting one can move the neck, and manual stabilisation is preferred. FIFA's protocols are written for trained pitchside medical teams, who fit the collar as part of full immobilisation while Orange holds manual in-line stabilisation throughout. Teach both, and say which applies to whom.`}]},{title:`Neck injury set piece in 3D`,blocks:[{kind:`text`,text:`The whole FIFA set piece for a suspected cervical spine injury, with the team's call-outs: MILS, A-c-B-C-D-E, collar, log roll onto the scoop, straps, blocks and tape, then the basket and the lift with six.`},{kind:`spine-3d`}]},{title:`Cervical collar`,blocks:[{kind:`video`,clip:c.cspine},{kind:`image`,src:e(`/img/fifa/cspine-protocol-v2.jpg`),alt:`FIFA Medical Set-Piece protocol for cervical spine injury: colour-coded tasks from assessment to extrication`,caption:`FIFA Medical Set-Piece protocol for cervical spine injury — each colour's tasks from MILS to extrication. Tap to open full size. © FIFA`},{kind:`device`,src:e(`/img/s5/collar.jpg`),alt:`Adjustable extrication cervical collar fitted on an adult, side view`,credit:{by:`James Heilman, MD`,license:`CC BY-SA 3.0`,href:`https://commons.wikimedia.org/wiki/File:LateralCollar.JPG`},model:{uid:`4baa44a5069b41b0bac9ce4038945c23`,name:`Cervical Collar`,by:`ChakkitPP`}},{kind:`image`,src:e(`/img/s5/collar-sizing.svg`),alt:l,caption:`How to size the collar, after the FIFA Emergency Care Manual: count fingerbreadths on the player, then find the same distance on the opened collar. Drawn for this guide — always follow the manufacturer's instructions.`},{kind:`text`,text:`Restricts excessive cervical movement when the spine cannot be clinically cleared — midline tenderness, neurological deficit, altered mental status, intoxication or distracting injury.`},{kind:`list`,ordered:!0,items:[`Maintain MILS throughout.`,`Assess the neck and select the correct size.`,`Prepare the collar before application.`,`Position the posterior section; support the chin in the chin piece.`,`Secure firmly without excessive tightening.`,`Check the collar does not compromise airway or breathing.`,`Continue spinal motion restriction; reassess neurological status.`]},{kind:`remember`,text:`MILS → ASSESS → SIZE → APPLY → SECURE → REASSESS`},{kind:`defs`,items:[{term:`FIFA sizing`,text:`Neutral head: line from the chin back to the sternomastoid; measure fingerbreadths down to trapezius; find the same distance on the collar's sizing marker (see the diagram). Between two sizes → start SMALLER (too big extends the neck).`},{term:`FIFA contraindication`,text:`Airway obstruction — keep MILS instead until the airway is dealt with.`},{term:`FIFA reminder`,text:`A collar alone does not immobilise: keep MILS until blocks, tape and a device are on. Recheck the player after fitting. Follow local guidance — some countries no longer use collars.`}]}]},{title:`Head immobiliser`,blocks:[{kind:`device`,src:e(`/img/s5/head.jpg`),alt:`Head immobiliser: orange lateral head blocks with forehead and chin straps on a board, ear opening visible`,credit:{by:`Stefan Schumacher`,license:`CC BY-SA 4.0`,href:`https://commons.wikimedia.org/wiki/File:Elk_paramedics_stretcher_Grey.jpg`},model:{uid:`1216e5d1e494433d92d36517337444ce`,name:`Spine board kit`,by:`Guardiano`}},{kind:`text`,text:`Lateral head support during spinal motion restriction and transport, used with an appropriate transfer device.`},{kind:`list`,ordered:!0,items:[`Maintain manual head stabilisation until fully secured.`,`Neutral position unless movement causes pain, resistance or neurological symptoms.`,`Place the lateral blocks evenly.`,`Secure forehead and chin straps per device design.`,`Keep access to the airway and ears.`,`Reassess airway and neurological status.`]},{kind:`remember`,text:`MANUAL CONTROL → BLOCKS → STRAPS → AIRWAY CHECK → REASSESS`}]},{title:`Spinal board & spider strap`,blocks:[{kind:`device`,src:e(`/img/s5/board.jpg`),alt:`Patient on a long board with head blocks and body straps, two paramedics at head and feet`,credit:{by:`Stefan Schumacher`,license:`CC BY-SA 4.0`,href:`https://commons.wikimedia.org/wiki/File:Elk_paramedics_stretcher_Grey.jpg`},model:{uid:`1216e5d1e494433d92d36517337444ce`,name:`Spine board kit`,by:`Guardiano`}},{kind:`text`,text:`Rigid surface for controlled extrication or transfer; spider straps secure the torso, pelvis and lower limbs.`},{kind:`list`,ordered:!0,items:[`The team leader coordinates; maintain spinal alignment.`,`Position the player centrally.`,`Secure the torso and pelvis first, then the legs.`,`Straps snug enough to control movement without impairing breathing or circulation.`,`Secure the head last while manual stabilisation is maintained.`,`Reassess ABC and neurological status.`]},{kind:`remember`,text:`BODY FIRST → LEGS → HEAD LAST → REASSESS`},{kind:`text`,text:`A scoop moves a trauma player only about 15°, compared with a 90° log roll. For cardiac arrest a rigid long board may give better compressions. A basket makes carrying a scoop or board safer.`},{kind:`list`,ordered:!0,items:[`FIFA extrication order (suspected neck injury): size and fit the collar — check the mouth can still open.`,`Move the player onto the scoop or spine board — Orange leads.`,`Apply straps — the first, centre strap lined up with the sternum.`,`Apply head blocks and fix them to the board, then tape.`,`Only now can MILS be released.`,`Slide the basket under the scoop and extricate with 6 people if possible.`]}]},{title:`Log roll (FIFA skill zone)`,blocks:[{kind:`defs`,items:[{term:`Head`,text:`MILS. Controls the move: explains the signal and says how far (90° log roll vs 15–20° tilt for a scoop).`},{term:`Chest`,text:`One hand on the player's far shoulder, one on the hip.`},{term:`Pelvis`,text:`One hand on the waist, the other under the knee.`},{term:`Legs`,text:`One hand under the lower leg, the other under the ankle.`},{term:`Fifth person`,text:`Places the board / device.`}]},{kind:`text`,text:`Use for suspected spinal injury, reduced GCS with possible head / neck injury, extrication, or a vomiting player needing spinal precautions.`}]},{title:`Scoop stretcher`,blocks:[{kind:`device`,src:e(`/img/s5/scoop.jpg`),alt:`Yellow scoop stretcher with its two halves joined and straps attached`,credit:{by:`Rama`,license:`CeCILL`,href:`https://commons.wikimedia.org/wiki/File:Civiere_a_aubes.jpg`},model:{uid:`fb718c84f1de4d7e80ec755b7de08a1e`,name:`Scoop Stretcher`,by:`ChakkitPP`}},{kind:`text`,text:`Lifting and transfer with reduced rolling — useful to move an injured player from the pitch to another transport device.`},{kind:`list`,ordered:!0,items:[`Set up below the feet (FIFA): basket in line with the player, 2–3 basket lengths from the feet; scoop out of the basket, extended and split, laid between the feet and the basket.`,`Adjust length to the player.`,`Separate the two halves.`,`Position each half alongside with minimal movement.`,`Connect head and foot ends securely.`,`Check all locks before lifting.`,`Enough rescuers; lift on the team leader's command.`,`Reassess after transfer.`]},{kind:`remember`,text:`SIZE → SPLIT → POSITION → LOCK → CHECK → LIFT`}]},{title:`Basket stretcher`,blocks:[{kind:`device`,src:e(`/img/s5/basket.jpg`),alt:`Orange basket stretcher on the ground`,credit:{by:`Christoph Baumgartinger`,license:`CC BY 2.5`,href:`https://commons.wikimedia.org/wiki/File:Korbtrage.jpg`},model:{uid:`9ce6ccf9cb67408c90dc4896babfe44a`,name:`Basket Stretcher`,by:`Greavsie93`}},{kind:`text`,text:`Protected carrying platform for difficult terrain or longer manual carries — stairs, slopes or poor pitch access.`},{kind:`list`,ordered:!0,items:[`Set up below the feet (FIFA): basket in line with the player, 2–3 basket lengths from the feet, scoop or board laid out between them.`,`Transfer the player into the basket with an appropriate technique / device.`,`Position centrally.`,`Secure torso, pelvis and legs.`,`Check straps and handles before movement.`,`Adequate personnel and coordinated commands.`,`Monitor the player continuously.`]},{kind:`remember`,text:`TRANSFER → CENTRE → SECURE → CHECK → CARRY → MONITOR`}]},{title:`Limb splints`,blocks:[{kind:`video`,clip:c.lowerLimb},{kind:`device`,src:e(`/img/s5/splint.jpg`),alt:`SAM splint: flexible padded splint, orange and blue, partly unrolled`,credit:{by:`Florian Thillmann`,license:`CC BY-SA 3.0`,href:`https://commons.wikimedia.org/wiki/File:SamSplint-straight.jpg`}},{kind:`list`,ordered:!0,items:[`Expose and inspect the injured limb where appropriate.`,`Control significant bleeding before splinting.`,`Check distal circulation, sensation and movement (CSM).`,`Immobilise the joints above and below the suspected fracture when practical.`,`Pad voids and bony prominences.`,`Secure without excessive pressure.`,`Recheck CSM.`]},{kind:`remember`,text:`CSM BEFORE → SPLINT → SECURE → CSM AFTER`}]},{title:`Extremity fracture (FIFA protocol)`,blocks:[{kind:`text`,text:`Any extremity fracture is a distracting injury — always do the full primary survey (A–E) and clear or protect the cervical spine first.`},{kind:`list`,ordered:!0,items:[`Stabilise the limb: one hand above and one below the fracture.`,`Inspect: swelling, deformity, bruising, wound. Feel: tenderness, crepitus, pulses and sensation. Active, then passive movement.`,`Analgesia — FIFA suggests inhaled methoxyflurane where available.`,`Wounds: clean thoroughly, cover with saline-soaked swabs and dress.`,`Apply the splint, then recheck circulation and neurology.`,`Open fracture (a wound over or near the break): refer to hospital; early antibiotics are advisable.`,`Extricate — or, if there is no neck injury and the player can help, assist them into the basket stretcher.`]}]},{title:`Arm sling`,blocks:[{kind:`device`,src:e(`/img/s5/sling.jpg`),alt:`Illustration of a broad arm sling supporting the forearm across the chest, tied at the neck`,credit:{by:`Laboratoires Servier (Servier Medical Art)`,license:`CC BY-SA 3.0`,href:`https://commons.wikimedia.org/wiki/File:Orthopedics_2_--_Smart-Servier.png`}},{kind:`list`,ordered:!0,items:[`Support the injured arm while applying.`,`Forearm comfortably across the chest.`,`Sling under the forearm, secured around the neck.`,`Keep the hand visible for circulation checks.`,`Reassess CSM.`]},{kind:`remember`,text:`SUPPORT → SLING → SECURE → CSM CHECK`}]},{title:`T-shirt arm sling (improvised)`,blocks:[{kind:`device`,src:e(`/img/s5/tshirt-sling.svg`),alt:`Two-step diagram: support the forearm across the chest, then fold the shirt hem up over it and secure at the collar`,credit:{by:`This guide`,license:`Diagram`,href:``}},{kind:`list`,ordered:!0,items:[`Use when no conventional sling is available or rapid pitchside support is needed.`,`Support the arm against the torso.`,`Use the lower part of the player's shirt to support the forearm.`,`Secure without restricting breathing or circulation.`,`Avoid manipulating a suspected fracture or dislocation.`,`Reassess CSM.`]},{kind:`remember`,text:`SUPPORT → FOLD / SECURE → COMFORT → CSM CHECK`}]},{title:`Pitchside scenarios`,blocks:[{kind:`cards`,items:[{title:`A · Suspected cervical spine injury`,sub:`Collision; on the ground with neck pain or neurological symptoms`,lines:[`Approach safely; primary survey.`,`Initiate MILS. Do not let the player sit or stand unnecessarily.`,`If the spine cannot be cleared: spinal motion restriction and controlled extrication (scoop stretcher + basket).`,`Repeat ABC and neurological reassessment.`]},{title:`B · Suspected lower-limb fracture`,sub:`Severe pain, swelling or deformity after a tackle`,lines:[`Primary survey; control bleeding.`,`Check CSM, support and splint, recheck CSM.`,`Scoop stretcher + basket for removal from the pitch — both set up below the feet, in line with the player.`]},{title:`C · Upper-limb injury`,sub:`Isolated shoulder / arm injury, otherwise stable`,lines:[`Assess the area and distal neurovascular status.`,`Arm sling or T-shirt sling.`,`Reassess comfort and circulation before transfer.`]}]}]},{title:`Common mistakes to avoid`,blocks:[{kind:`list`,items:[`Applying equipment before an appropriate primary assessment.`,`Releasing MILS too early.`,`Incorrect collar sizing.`,`Uncoordinated lifting without a clear leader.`,`Straps too loose or too tight.`,`Moving a suspected fracture to get a 'normal' position.`,`Not checking CSM before and after splinting.`,`Not reassessing ABC and neurology after immobilisation or transfer.`]},{kind:`text`,text:`Device-specific manufacturer instructions and your local clinical protocol take precedence where applicable.`}]}],source:`FIFA Emergency Care Manual: collar sizing, log roll and the extrication set piece. The step lists for each device and the sling techniques are general practical guidance; always follow the manufacturer's instructions.`},{id:`5`,short:`Emergency care bag`,title:`Preparation of the Football Emergency Care Bag`,subtitle:`FIFA's standard bag, plus a fuller local checklist, layout and critical fails`,sections:[{title:`How many bags — local planning guide`,blocks:[{kind:`table`,head:[`Match setting`,`Primary bags`,`Backup`],rows:[[`1 football pitch`,`1 fully equipped bag`,`1 reserve / secondary bag`],[`2 pitches operating simultaneously`,`2 bags`,`1 reserve`],[`3 pitches`,`3 bags`,`1 reserve`],[`Tournament, multiple simultaneous matches`,`1 bag per active pitch`,`At least 1 central reserve`],[`High-risk / large tournament`,`1 per pitch + dedicated trauma/medical team bag`,`Additional reserve`]]},{kind:`alert`,title:`Do not rely on one bag shared between pitches`,text:`The bag must be immediately accessible at the pitch where the emergency occurs. Emergency planning should be venue-specific and rehearsed before the event.`},{kind:`text`,text:`Single football match: 1 × pitchside emergency medical bag + 1 × backup / resupply bag + 1 × AED immediately available pitchside. The AED should not be buried inside the medical bag — it needs to be rapidly accessible.`}]},{title:`Local checklist · A. Airway`,blocks:[{kind:`table`,head:[`Equipment`,`Qty`],rows:[[`Oropharyngeal airway`,`1 set`],[`Nasopharyngeal airway`,`1 set`],[`LMA / supraglottic airway / i-gel size 3, 4, 5`,`1`],[`Lubricating gel`,`1`],[`Pocket mask with O₂ port`,`1`],[`Magill forceps`,`1`],[`Portable suction`,`1`],[`Suction catheters, appropriate sizes`,`2–3 each`],[`Pen torch`,`1`]]}]},{title:`Local checklist · B. Breathing / oxygen`,blocks:[{kind:`table`,head:[`Equipment`,`Qty`],rows:[[`Adult BVM set`,`1`],[`Adult face masks`,`2`],[`Oxygen tubing`,`2`],[`Non-rebreather oxygen mask`,`2`],[`Simple oxygen mask`,`1`],[`Nebuliser mask / set`,`1–2`],[`Oxygen cylinder`,`Separate dedicated cylinder`],[`Oxygen regulator`,`1`],[`Pulse oximeter`,`1`],[`Spacer device`,`1`]]},{kind:`alert`,text:`Oxygen availability should be considered part of the pitchside emergency response, not simply an optional accessory.`}]},{title:`Local checklist · C. Circulation / cardiac`,blocks:[{kind:`table`,head:[`Equipment`,`Qty`],rows:[[`AED`,`1`],[`AED adult pads`,`1 set + spare if available`],[`AED paediatric pads`,`According to event population`],[`BP machine`,`1`],[`Adult BP cuffs`,`1–2`],[`Stethoscope`,`1`],[`IV cannula 14G / 16G / 18G / 20G / 22G`,`2 each`],[`Tourniquet`,`2`],[`Alcohol swabs`,`10`],[`IV dressing / Tegaderm`,`5`],[`5 mL syringe`,`5`],[`10 mL syringe`,`5`],[`Needles`,`Assorted`],[`IV giving set`,`2`],[`Normal saline 0.9%`,`According to clinical protocol`],[`Sharps container`,`1`]]},{kind:`text`,text:`Rapid recognition, CPR and defibrillation are critical components of field-of-play cardiac emergency management.`}]},{title:`Local checklist · Diagnostics`,blocks:[{kind:`list`,items:[`BP machine`,`Stethoscope`,`Pulse oximeter`,`Glucometer, blood glucose strips, lancets`,`Thermometer`,`Pen torch`,`Watch / timer`,`ECG machine — preferably with the medical team / medical room rather than inside the bag`]}]},{title:`Local checklist · Heat / environment`,blocks:[{kind:`text`,text:`Essential wherever football is played in heat and humidity.`},{kind:`list`,items:[`Instant cold packs`,`Ice; ice-water immersion capability where appropriate`,`Cooling towels, wet towels, cooling blanket`,`Spray bottle`,`Water, oral rehydration solution`,`Fan`,`Thermal blanket`]},{kind:`alert`,text:`The pre-event emergency plan should specifically address exertional heat illness and rapid cooling before transport.`},{kind:`link`,to:`/heat`,label:`Heat illness: cool first, transport second →`,text:`Heat risk from a WBGT reading, spotting heat stroke, and a cooling simulator.`}]},{title:`Medications — emergency drug pouch`,blocks:[{kind:`alert`,title:`Follow local authority`,text:`Drugs and quantities must follow the event medical director's standing orders, prescriber authority, national regulations, formulary and local SOP. Do not place prescription medicines into a generic football bag without an approved medication protocol.`},{kind:`table`,head:[`Clinical problem`,`Medication category`],rows:[[`Anaphylaxis`,`Adrenaline / epinephrine IM`],[`Asthma / bronchospasm`,`Salbutamol ± ipratropium — as an inhaler (with a spacer) and as nebules for a nebuliser, according to protocol`],[`Hypoglycaemia`,`Oral glucose / dextrose gel`],[`Severe hypoglycaemia / unconscious`,`Glucagon IM (if available), or parenteral glucose / dextrose according to protocol`],[`Chest pain — suspected cardiac`,`Aspirin and GTN spray, according to protocol`],[`Pain`,`Analgesia according to approved formulary`],[`Allergic reaction`,`Antihistamine according to protocol`],[`Cardiac arrest`,`Resuscitation drugs only where advanced medical team / protocol supports them`],[`IV fluid requirement`,`Isotonic crystalloid according to clinical indication`]]}]},{title:`One way to lay out a local bag — 11 compartments`,blocks:[{kind:`defs`,items:[{term:`1 · Airway`,text:`OPA / NPA / i-gel / lubricant`},{term:`2 · BVM & oxygen`,text:`BVM / masks / oxygen masks / nebuliser`},{term:`3 · Suction`,text:`Suction device / catheters`},{term:`4 · Circulation`,text:`IV cannulas / syringes / tourniquet / IV set`},{term:`5 · Drugs`,text:`Approved emergency medications`},{term:`6 · Trauma`,text:`Gauze / dressing / haemorrhage control / shears`},{term:`7 · Splints`,text:`Splints / sling / bandages / cervical collar`},{term:`8 · Diagnostics`,text:`BP / SpO₂ / glucose / thermometer / stethoscope`},{term:`9 · PPE & sharps`,text:`Gloves / eye protection / sharps box / waste bags`},{term:`10 · Concussion / documentation`,text:`SCAT6 / CRT / forms / pen`},{term:`11 · Heat / environmental`,text:`Cold packs / cooling towels / oral rehydration solution / fan`}]}]},{title:`FIFA's standard bag (FECB 2022) — the minimum`,blocks:[{kind:`text`,text:`FIFA's standard bag is a minimum. Teams may add items, but FIFA recommends not altering the basic inventory, so different teams can work together on the same pitch with the same kit. Contents suit players over 14 years and over 50 kg.`},{kind:`link`,to:`/bag`,hash:`pack`,label:`Game: pack the bag →`,text:`Drag each item into its tray against the clock — and bin the faulty kit.`},{kind:`defs`,items:[{term:`Airway`,text:`Suction · NPA 6, 7, 8 · OPA 2, 3, 4 · i-gel 4, 5 · lubricant · Magill forceps`},{term:`Breathing`,text:`BVM · trauma O2 mask · nebuliser mask · pocket mask · spacer`},{term:`Circulation`,text:`IV cannula 14G, 16G · syringes 5 & 10 mL · needles · tourniquet · swabs · giving set · AED (own compartment)`},{term:`Cervical spine`,text:`Hard collar`},{term:`Diagnostics`,text:`Stethoscope · BP · glucometer · SpO₂ probe · peak flow · pen torch · thermometer`},{term:`Wounds · PPE`,text:`Suture set, steristrips, gauze, shears, eye wash · aprons, gloves, gel, glasses, sharps bin`}]},{kind:`list`,items:[`Oxygen is clipped to the outside of the bag (cannot be flown) — stadiums should provide it.`,`IV fluids and drugs are added per the clinician / local protocol — they count as medication.`,`Check the bag against the checklist before AND after every match: batteries charged, adjuncts replaced, everything in date.`,`The bag page follows FIFA's current factsheet from the bag's supplier, which differs slightly from this 2022 list: for example 14G and 18G cannulas, and the Philips HeartStart FRx AED.`]},{kind:`text`,text:`Other recommended pitchside kit (FIFA):`},{kind:`list`,items:[`Scoop stretcher (preferred over a spinal / long board for trauma, where affordable)`,`Spider straps or clip-on straps · head huggers / restraints`,`Basket stretcher — carrying a scoop or board is far safer inside a basket`,`Splints (vacuum or individual)`]}]},{title:`Critical fail items`,blocks:[{kind:`list`,ordered:!0,items:[`No AED available`,`Expired AED battery or expired defibrillator pads`,`No oxygen / BVM`,`No suction when required by the service level`,`Unable to identify emergency access / ambulance plan`,`Expired / unavailable emergency medication`,`Bag not accessible pitchside`,`Unable to activate EMS / ambulance`,`Unsafe medication administration`]}]}],source:`FIFA's standard bag: FIFA Emergency Care Manual, Ch.10. The bag-number guide, the longer local checklist, the 11-compartment layout and the critical-fail list are practical additions that go beyond FIFA's minimum.`},{id:`6`,short:`Concussion (FOCUS)`,title:`On-Pitch Concussion Assessment — FIFA FOCUS`,subtitle:`Suspect and protect: the 11 FOCUS domains, what happens after a suspected concussion, and the graduated return to football`,sections:[{title:`Suspect and protect`,blocks:[{kind:`alert`,title:`Suspected concussion = remove from play immediately`,text:`The on-pitch assessment does not diagnose concussion. It decides whether any sign or symptom raises suspicion — and if it does, the player comes off and does not go back on that day.`},{kind:`list`,items:[`FOCUS: FIFA's Football-Specific Standardised On-Pitch Concussion Assessment Protocol.`,`11 domains, checked from the touchline, on approaching the player, on the pitch and back at the touchline.`,`Some abnormal findings lower your threshold for concern — carry on with the assessment. Others mean substitute the player for assessment and treatment off the pitch.`,`Footballers who play on with a concussion recover more slowly, perform worse and risk further injury.`]},{kind:`video`,clip:o}]},{title:`The 11 domains`,blocks:[{kind:`table`,head:[`Where · domain`,`Check`,`If abnormal`],rows:r.flatMap(e=>e.domains.filter(e=>e.outcome!==`step`).map(t=>[`${e.where} · ${t.domain}`,t.items?`${t.lead} ${t.items.join(` · `)}`:t.lead,t.outcome===`sub`?`Substitute — assess off the pitch`:`Lower threshold, carry on`]))},{kind:`info`,title:`On the pitch, in this order`,text:`Level of consciousness and the cervical spine first. Only then ask the player to sit up, and go on to symptoms, orientation, balance, proprioception and eye movements.`},{kind:`text`,text:`ACVPU = Alert, new Confusion, Voice, Pain, Unresponsive.`}]},{title:`After a suspected concussion`,blocks:[{kind:`list`,items:a}]},{title:`Graduated return to football`,blocks:[{kind:`list`,ordered:!0,items:[...n]},{kind:`text`,text:i}]},{title:`FOCUS card and FIFA's documents`,blocks:[{kind:`link`,to:`/focus`,label:`Open the FOCUS page →`,text:`FIFA's lanyard card (both sides), the full FOCUS resources and FIFA's concussion protocols.`},{kind:`link`,to:`/focus`,hash:`focus-signs`,label:`Practise: spot the sign in 3D →`,text:`A player acts out the visible signs — name each one and what FOCUS asks for.`}]}],source:`FIFA FOCUS (lanyard card, April 2026) and FIFA's Concussion Protocol for Medical Staff (August 2024). A study summary: FIFA's documents are the authoritative source.`}],f=[`1`,`2`,`3`,`4`,`5`,`6`];function p(e){return f.includes(e)?d.find(t=>t.id===e):void 0}export{d as i,p as n,u as r,l as t};